edits.new_text:
var startLeft = new Date(dateLeft.getTime())
startLeft.setHours(0, 0, 0, 0)
var startRight = new Date(dateRight.getTime())
startRight.setHours(0, 0, 0, 0)

var result = Math.round((startLeft - startRight) / MILLISECONDS_IN_DAY)

var timeLeft = dateLeft.getTime() - startLeft.getTime()
var timeRight = dateRight.getTime() - startRight.getTime()

if (result > 0 && timeLeft < timeRight) {
  result--
} else if (result < 0 && timeLeft > timeRight) {
  result++
}

return result
